    "<svg viewBox=\"0 0 230 190\" width=\"230\" role=\"img\" aria-label=\"Çizgi grafiği B\"><rect x=\"0\" y=\"0\" width=\"230\" height=\"190\" fill=\"#ffffff\"/><defs><marker id=\"hB\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#1e293b\"/></marker></defs><line x1=\"40\" y1=\"150\" x2=\"215\" y2=\"150\" stroke=\"#1e293b\" stroke-width=\"2\" marker-end=\"url(#hB)\"/><line x1=\"40\" y1=\"150\" x2=\"40\" y2=\"25\" stroke=\"#1e293b\" stroke-width=\"2\" marker-end=\"url(#hB)\"/><text x=\"215\" y=\"184\" font-size=\"12\" text-anchor=\"end\" fill=\"#1e293b\">Blok sayısı</text><text x=\"44\" y=\"19\" font-size=\"12\" text-anchor=\"start\" fill=\"#1e293b\">İz derinliği</text><text x=\"75\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">1</text><text x=\"110\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">2</text><text x=\"145\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">3</text><text x=\"180\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">4</text><line x1=\"40\" y1=\"150\" x2=\"180\" y2=\"50\" stroke=\"#dc2626\" stroke-width=\"3\"/><line x1=\"40\" y1=\"150\" x2=\"180\" y2=\"50\" stroke=\"#1e3a8a\" stroke-width=\"3\"/><text x=\"186\" y=\"54\" font-size=\"12\" text-anchor=\"start\" fill=\"#1e293b\" font-weight=\"bold\">K ve L</text></svg>",
    "<svg viewBox=\"0 0 230 190\" width=\"230\" role=\"img\" aria-label=\"Çizgi grafiği C\"><rect x=\"0\" y=\"0\" width=\"230\" height=\"190\" fill=\"#ffffff\"/><defs><marker id=\"hC\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#1e293b\"/></marker></defs><line x1=\"40\" y1=\"150\" x2=\"215\" y2=\"150\" stroke=\"#1e293b\" stroke-width=\"2\" marker-end=\"url(#hC)\"/><line x1=\"40\" y1=\"150\" x2=\"40\" y2=\"25\" stroke=\"#1e293b\" stroke-width=\"2\" marker-end=\"url(#hC)\"/><text x=\"215\" y=\"184\" font-size=\"12\" text-anchor=\"end\" fill=\"#1e293b\">Blok sayısı</text><text x=\"44\" y=\"19\" font-size=\"12\" text-anchor=\"start\" fill=\"#1e293b\">İz derinliği</text><text x=\"75\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">1</text><text x=\"110\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">2</text><text x=\"145\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">3</text><text x=\"180\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">4</text><line x1=\"40\" y1=\"150\" x2=\"180\" y2=\"40\" stroke=\"#dc2626\" stroke-width=\"3\"/><line x1=\"40\" y1=\"150\" x2=\"180\" y2=\"95\" stroke=\"#1e3a8a\" stroke-width=\"3\"/><text x=\"186\" y=\"44\" font-size=\"12\" text-anchor=\"start\" fill=\"#dc2626\" font-weight=\"bold\">K</text><text x=\"186\" y=\"99\" font-size=\"12\" text-anchor=\"start\" fill=\"#1e3a8a\" font-weight=\"bold\">L</text></svg>",
    "<svg viewBox=\"0 0 230 190\" width=\"230\" role=\"img\" aria-label=\"Çizgi grafiği D\"><rect x=\"0\" y=\"0\" width=\"230\" height=\"190\" fill=\"#ffffff\"/><defs><marker id=\"hD\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#1e293b\"/></marker></defs><line x1=\"40\" y1=\"150\" x2=\"215\" y2=\"150\" stroke=\"#1e293b\" stroke-width=\"2\" marker-end=\"url(#hD)\"/><line x1=\"40\" y1=\"150\" x2=\"40\" y2=\"25\" stroke=\"#1e293b\" stroke-width=\"2\" marker-end=\"url(#hD)\"/><text x=\"215\" y=\"184\" font-size=\"12\" text-anchor=\"end\" fill=\"#1e293b\">Blok sayısı</text><text x=\"44\" y=\"19\" font-size=\"12\" text-anchor=\"start\" fill=\"#1e293b\">İz derinliği</text><text x=\"75\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">1</text><text x=\"110\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">2</text><text x=\"145\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">3</text><text x=\"180\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" fill=\"#1e293b\">4</text><line x1=\"40\" y1=\"150\" x2=\"180\" y2=\"40\" stroke=\"#dc2626\" stroke-width=\"3\"/><line x1=\"40\" y1=\"150\" x2=\"180\" y2=\"150\" stroke=\"#1e3a8a\" stroke-width=\"3\"/><text x=\"186\" y=\"44\" font-size=\"12\" text-anchor=\"start\" fill=\"#dc2626\" font-weight=\"bold\">K</text><text x=\"186\" y=\"142\" font-size=\"12\" text-anchor=\"start\" fill=\"#1e3a8a\" font-weight=\"bold\">L</text></svg>"
